from flask import Flask, request
import shlex
import logging

app = Flask(__name__)

ALLOWLIST = ['ls', 'pwd', 'echo']

@app.route('/execute_bash')
def execute_bash():
    command = request.args.get('command')
    if command not in ALLOWLIST:
        return 'Invalid command', 400
    try:
        sanitized_command = shlex.split(command)
        result = subprocess.run(sanitized_command, capture_output=True, text=True, check=True)
        app.logger.info(f'Executed command: {command}')
        return result.stdout, 200
    except ValueError:
        return 'Invalid command', 400
    except subprocess.CalledProcessError as e:
        app.logger.error(f'Command execution failed: {e}')
        return 'Internal server error', 500
    except Exception:
        return 'Internal server error', 500

