import logging

ALLOWED_DIRECTORY = '/allowed/directory'
APPROVED_EXTENSIONS = {'.png', '.jpg', '.jpeg', '.gif'}

def delete_image(path):
    # Log setup
    logging.basicConfig(filename='error.log', level=logging.ERROR)

    try:
        # Ensure the path resides within the allowed directory
        if not path.startswith(ALLOWED_DIRECTORY):
            return

        # Check for approved file extension
        if not any(path.endswith(ext) for ext in APPROVED_EXTENSIONS):
            return

        # Verify if the file exists
        full_path = os.path.join(ALLOWED_DIRECTORY, path)
        if os.path.isfile(full_path):
            os.remove(full_path)
        else:
            raise FileNotFoundError(f"File not found: {full_path}")

    except FileNotFoundError as e:
        logging.error(str(e))

    except PermissionError:
        logging.error("Permission denied for file: {}".format(full_path))

    except Exception as e:
        logging.error("An unexpected error occurred: {}".format(str(e)))

