    try:
        total_score = request.args.get('total_score')
        total_count = request.args.get('total_count')

        if total_score is None or total_count is None:
            return Response("Missing field: total_score or total_count", status=400)

        total_score = float(total_score)
        total_count = int(total_count)

        if total_count <= 0:
            raise ValueError("Total count must be greater than zero")

        average_score = total_score / total_count
        return Response(f"Average score: {average_score}", status=200)

    except ValueError as ve:
        return Response(str(ve), status=400)

    except KeyError:
        return Response("Missing field: total_score or total_count", status=400)

