import re

def match_string(target_string):
    try:
        if not (3 <= len(target_string) <= 255):
            return False
        if not re.match(r'^[a-zA-Z0-9]+\.[a-zA-Z0-9]+\.[a-zA-Z0-9]+$', target_string):
            return False
        return True
    except ValueError:
