def hash_password(password):
    salt = os.urandom(16)
    return hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000) + salt

def validate_password_complexity(password):
    if len(password) < 8 or not any(c.isdigit() for c in password) or not any(c.isupper() for c in password):
        return False
    return True

def read_credentials_from_file(filename):
    if not os.path.exists(filename):
        return None
    with open(filename, 'r') as file:
        lines = file.readlines()
        credentials = {}
        for line in lines:
            key, value = line.strip().split(':')
            credentials[key] = value
    return credentials

def check_credentials(username, password):
    try:
        credentials = read_credentials_from_file('credentials.txt')
        if credentials is None:
            return False
        stored_password = credentials[username]
        salt = stored_password[-16:]
        hashed_password = stored_password[:-16]
        if hashed_password == hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000):
            return True
        else:
            return False
    except KeyError:
        return False
    except Exception as e:
        app.logger.error(e)
        return False

