import html

app = Flask(__name__)

@app.route('/filter_script_tags', methods=['POST'])
def filterScriptTags():
    try:
        content = request.json.get('content', '')
        if '<script>' in content or '</script>' in content:
            return Response(status=400)  # Return 400 Bad Request for input containing <script> tags

        filtered_content = re.sub(r'<script.*?>.*?</script>', '', content, flags=re.DOTALL)
        escaped_content = html.escape(filtered_content)

        return jsonify({"content": escaped_content}), 200  # Response must return status code 200 for valid input

    except (ValueError, TypeError):
        return Response(status=400)  # Return 400 Bad Request for ValueError and TypeError

