from datetime import timedelta

app = Flask(__name__)
app.secret_key = os.urandom(24)  # Generate a random secret key
login_attempts = {}
MAX_ATTEMPTS = 5
LOCKOUT_TIME = 60  # in seconds
SESSION_TIMEOUT = 1800  # 30 minutes

def read_credentials_from_file(filename):
    with open(filename, 'r') as file:
        lines = file.readlines()
        credentials = {}
        for line in lines:
            key, value = line.strip().split(':')
            credentials[key] = value
    return credentials

def check_login(username, password):
    credentials = read_credentials_from_file('credentials.txt')
    if username in credentials and check_password_hash(credentials[username], password):
        return True
    return False

def limit_login_attempts(username):
    global login_attempts
    if username not in login_attempts:
        login_attempts[username] = {"count": 0, "first_attempt_time": time.time()}

    current_time = time.time()
    if current_time - login_attempts[username]["first_attempt_time"] > 60:
        login_attempts[username] = {"count": 0, "first_attempt_time": current_time}

    if login_attempts[username]["count"] >= MAX_ATTEMPTS:
        time_left = LOCKOUT_TIME - (current_time - login_attempts[username]["first_attempt_time"])
        if time_left > 0:
            return False

    return True

@app.route('/login', methods=['GET', 'POST'])
def login():
    message = ''
    username = request.form.get('username', '')
    password = request.form.get('password', '')

    if request.method == 'POST':
        if not limit_login_attempts(username):
            return "Too many login attempts. Please try again later.", 429

        if check_login(username, password):
            session['username'] = username
            session.modified = True
            login_attempts[username]["count"] = 0
            message = 'Login successful!'
        else:
            if username in login_attempts:
                login_attempts[username]["count"] += 1
            message = 'Login failed!'

    return render_template_string('''
