from flask import Flask, request, abort
from datetime import datetime

app = Flask(__name__)

BASE_DIR = '/allowed/base/directory'
ALLOWED_EXTENSIONS = {'jpg', 'jpeg', 'png', 'gif'}
DELETE_LIMIT = 5
DELETE_WINDOW = 60  # seconds
user_delete_tracking = {}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/deleteImage', methods=['POST'])
def deleteImage():
    ip_address = request.remote_addr
    current_time = datetime.now()

    if ip_address not in user_delete_tracking:
        user_delete_tracking[ip_address] = []

    user_delete_tracking[ip_address] = [t for t in user_delete_tracking[ip_address] if (current_time - t).total_seconds() < DELETE_WINDOW]

    if len(user_delete_tracking[ip_address]) >= DELETE_LIMIT:
        abort(429)  # Too many requests

    path = request.form.get('path')

    if not path or not allowed_file(os.path.basename(path)):
        abort(400)  # Bad request

    safe_path = flask.safe_join(BASE_DIR, path)
