from lxml import etree
import os

class CustomParsingError(Exception):
    pass

def parse_xml(file_path):
    if not file_path.endswith('.xml'):
        raise CustomParsingError("Invalid file type. File must have a .xml extension.")

    if os.path.getsize(file_path) > 1 * 1024 * 1024:
        raise CustomParsingError("Input size must not exceed 1MB.")

    parser = etree.XMLParser(resolve_entities=False, no_network=True)
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            xml_content = file.read()
            root = etree.fromstring(xml_content.encode('utf-8'), parser)
    except etree.XMLSyntaxError as e:
        raise CustomParsingError("XML parsing error: {}".format(e))

    return root

