import os
import tempfile
import logging

ALLOWED_EXTENSIONS = {'.txt', '.log'}
MAX_SIZE = 1024 * 1024  # 1 MB
ALLOWED_PATH = '/allowed/path'

def log_error(e):
    logging.error(f"Error: {e}")

def is_valid_path(file_path):
    absolute_path = os.path.abspath(file_path)
    return absolute_path.startswith(ALLOWED_PATH)

def has_valid_extension(file_name):
    return any(file_name.endswith(ext) for ext in ALLOWED_EXTENSIONS)

def write_results(results):
    try:
        if not isinstance(results, str):
            return None
        if len(results.encode('utf-8')) > MAX_SIZE:
            return None
        fd, temp_file_path = tempfile.mkstemp(suffix=".txt")
        if not is_valid_path(temp_file_path) or not has_valid_extension(temp_file_path):
            os.close(fd)
            os.remove(temp_file_path)
            return None
        with os.fdopen(fd, 'w', encoding='utf-8') as temp_file:
            temp_file.write(results)
        return temp_file_path
    except OSError as e:
        log_error(e)
        return None

