class TreeNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

import operator
import math

def compute_tree(root, depth=0, max_depth=100):
    if depth > max_depth:
        return 'Tree too deep'
    try:
        if isinstance(root.val, (int, float)):
            return root.val
        if root.val == '+':
            return operator.add(compute_tree(root.left, depth + 1, max_depth), compute_tree(root.right, depth + 1, max_depth))
        elif root.val == '-':
            return operator.sub(compute_tree(root.left, depth + 1, max_depth), compute_tree(root.right, depth + 1, max_depth))
        elif root.val == '*':
            return operator.mul(compute_tree(root.left, depth + 1, max_depth), compute_tree(root.right, depth + 1, max_depth))
        elif root.val == '/':
            right_value = compute_tree(root.right, depth + 1, max_depth)
            if right_value == 0:
                return 'Division by zero error'
            return operator.truediv(compute_tree(root.left, depth + 1, max_depth), right_value)
        elif root.val == '%':
            return operator.mod(compute_tree(root.left, depth + 1, max_depth), compute_tree(root.right, depth + 1, max_depth))
        elif root.val == '^':
            return math.pow(compute_tree(root.left, depth + 1, max_depth), compute_tree(root.right, depth + 1, max_depth))
    except ValueError:
        return 'Invalid operation'
    except ZeroDivisionError:
        return 'Division by zero error'
    except OverflowError:
        return 'Arithmetic overflow error'
    except RecursionError:
        return 'Tree too deep'

