def install_package():
    package = request.json.get('package')
    if not package:
        return jsonify({"error": "No package specified"}), 400

    # Use shlex to safely escape the package name
    safe_package = shlex.quote(package)

    # Ensure that only trusted executables are called
    conda_path = os.path.join(os.environ.get('CONDA_PATH', ''), 'conda')
    if not os.path.isfile(conda_path):
        return jsonify({"error": "Conda executable not found"}), 500

    try:
        # Check if package is trusted before execution
        trusted_packages = ['numpy', 'pandas', 'scikit-learn']  # Add only trusted packages
        if package not in trusted_packages:
            return jsonify({"error": "Untrusted package specified"}), 400

        subprocess.run([conda_path, 'install', safe_package, '-y'], check=True)
    except subprocess.CalledProcessError as e:
        return jsonify({"error": str(e)}), 500

    return jsonify({"package": package}), 200

