import hmac
import hashlib

key = b"e179017a-62b0-4996-8a38-e91aa9f1"
msg = b"Test"

def sign(pre_key, imsg, alg):
    if len(pre_key) < 16 or len(imsg) == 0:
        return False
    return hmac.new(pre_key, imsg, alg).digest()

def verify(msg, sig, pre_key, alg):
    try:
        if len(pre_key) < 16 or len(msg) == 0 or len(sig) != hashlib.new(alg).digest_size:
            return False
        expected_sig = hmac.new(pre_key, msg, alg).digest()
        return hmac.compare_digest(expected_sig, sig)
    except ValueError:
        return False
    except TypeError:
        return False

