    except etree.XMLSyntaxError:
        return jsonify({"error": "Bad Request"}), 400

    try:
        xslt_doc = etree.parse(xslt_file)
        transform = etree.XSLT(xslt_doc)
        result = transform(xml_doc)
        return str(result), 200
    except Exception:
